import{_ as o,r as s,o as p,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Файловые настройки - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Структура файла конфигурации","slug":"структура-фаила-конфигурации","link":"#структура-фаила-конфигурации","children":[]},{"level":2,"title":"Доступ к значениям конфигурации","slug":"доступ-к-значениям-конфигурации","link":"#доступ-к-значениям-конфигурации","children":[]},{"level":2,"title":"Переопределение значений конфигурации","slug":"переопределение-значении-конфигурации","link":"#переопределение-значении-конфигурации","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/extend/settings/file-settings.md","filePath":"3.x/ru/extend/settings/file-settings.md"}'),i={name:"3.x/ru/extend/settings/file-settings.md"};function g(u,n,d,m,k,h){const e=s("pre-heading"),t=s("post-heading");return p(),c("div",null,[a(e),n[0]||(n[0]=l("h1",null,"Файловые настройки",-1)),a(t),n[1]||(n[1]=r(`<p>Файловые настройки хранят значения в файлах и могут быть переопределены переменными окружения или файлами приложения.</p><h2 id="структура-фаила-конфигурации"><a href="#структура-фаила-конфигурации" class="header-anchor">#</a> Структура файла конфигурации</h2><p>Плагины могут использовать файловую конфигурацию в поддиректории <strong>config</strong> директории плагина. Ниже приведён пример директории <strong>config</strong> плагина.</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── todo
|           └── <code>config</code>
|               ├── config.php  <em>← Файл конфигурации</em>
|               └── custom.php  <em>← Файл конфигурации</em></p>
</code></pre><p>Файлы конфигурации — это PHP-скрипты, которые определяют и возвращают <strong>массив</strong>. Ниже приведён пример файла конфигурации <strong>config.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;display&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">5</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="доступ-к-значениям-конфигурации"><a href="#доступ-к-значениям-конфигурации" class="header-anchor">#</a> Доступ к значениям конфигурации</h2><p>Используйте фасад <code>Config</code> для доступа к значениям конфигурации, определённым в файле конфигурации. Метод <code>get</code> принимает имя плагина и имя конфигурации (первый аргумент) в следующем формате: <strong>acme.demo::maxItems</strong>. Вы также можете определить значение по умолчанию (второй аргумент), которое возвращается, если параметр конфигурации не существует.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$maxItems</span> <span class="token operator">=</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.demo::maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Использование другого имени файла конфигурации влияет на имя ключа. Например, файл конфигурации с именем <strong>custom.php</strong> добавит префикс <code>custom</code> к имени ключа в следующем формате: <strong>acme.demo::custom.maxItems</strong>. Следующий пример основан на файле конфигурации с именем <strong>custom.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$maxItems</span> <span class="token operator">=</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.demo::custom.maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="переопределение-значении-конфигурации"><a href="#переопределение-значении-конфигурации" class="header-anchor">#</a> Переопределение значений конфигурации</h2><p>Файл конфигурации плагина может быть переопределён приложением путём создания соответствующего локального файла конфигурации. Например, для переопределения <strong>plugins/acme/demo/config/config.php</strong> создайте файл <strong>config/acme/todo/config.php</strong>.</p><pre class="dir-container"><code><p>├── config
|   └── <code>acme</code>
|       └── <code>todo</code>
|           └── config.php  <em>← Файл переопределения</em></p>
</code></pre><p>Внутри переопределённого файла конфигурации вы можете возвращать только те значения, которые хотите переопределить.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">20</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите использовать разные конфигурации для разных окружений (например: <strong>dev</strong>, <strong>production</strong>), рассмотрите использование хелпера <code>env()</code> для получения значения из переменной окружения. Функция <code>env()</code> принимает имя переменной окружения (первый аргумент) и необязательное значение по умолчанию, если переменная не существует (второй аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;ACME_TODO_MAX_ITEMS&#39;</span><span class="token punctuation">,</span> <span class="token number">25</span><span class="token punctuation">)</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</span></code></pre></div><p>Это изменит значение <code>maxItems</code>, когда переменная окружения <code>ACME_TODO_MAX_ITEMS</code> будет установлена в любое другое значение. Например, внутри файла <strong>.env</strong> приложения. Смотрите <a href="./../../setup/configuration.html">статью о конфигурации</a>, чтобы узнать, как изменять эти значения в зависимости от окружения.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">ACME_TODO_MAX_ITEMS</span><span class="token punctuation">=</span><span class="token value attr-value">10</span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../../setup/configuration.html">Общая конфигурация</a></li></ul></div>`,22))])}const v=o(i,[["render",g]]);export{_ as __pageData,v as default};
